// Generated from NIST OSCAL content. Do not edit by hand.
export const FAMILY_PE: NistCatalogFamily = {"code":"PE","name":"Physical and Environmental Protection","controls":[{"id":"PE-1","oscal_id":"pe-1","family":"PE","title":"Policy and Procedures","statement":"a. Develop, document, and disseminate to <organization-defined personnel or roles>:\n  Develop, document, and disseminate to <organization-defined personnel or roles>:\n  1. <organization-defined parameter> physical and environmental protection policy that:\n    <organization-defined parameter> physical and environmental protection policy that:\n    (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and\n    (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and\n  2. Procedures to facilitate the implementation of the physical and environmental protection policy and the associated physical and environmental protection controls;\nb. Designate an <official> to manage the development, documentation, and dissemination of the physical and environmental protection policy and procedures; and\nc. Review and update the current physical and environmental protection:\n  Review and update the current physical and environmental protection:\n  1. Policy <frequency> and following <events> ; and\n  2. Procedures <frequency> and following <events>.","supplemental_guidance":"Physical and environmental protection policy and procedures address the controls in the PE family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of physical and environmental protection policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to physical and environmental protection policy and procedures include assessment or audit findings, security incidents or breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure.","implementation_level":"organization","parameters":[{"id":"pe-1_prm_1","label":"organization-defined personnel or roles"},{"id":"pe-01_odp.01","label":"personnel or roles"},{"id":"pe-01_odp.02","label":"personnel or roles"},{"id":"pe-01_odp.03","label":"","choices":["organization-level","mission/business process-level","system-level"],"how_many":"one-or-more"},{"id":"pe-01_odp.04","label":"official"},{"id":"pe-01_odp.05","label":"frequency"},{"id":"pe-01_odp.06","label":"events"},{"id":"pe-01_odp.07","label":"frequency"},{"id":"pe-01_odp.08","label":"events"}],"objectives":[{"id":"pe-1_obj.a-1","label":"PE-01a.[01]","text":"a physical and environmental protection policy is developed and documented;"},{"id":"pe-1_obj.a-2","label":"PE-01a.[02]","text":"the physical and environmental protection policy is disseminated to {{ insert: param, pe-01_odp.01 }};"},{"id":"pe-1_obj.a-3","label":"PE-01a.[03]","text":"physical and environmental protection procedures to facilitate the implementation of the physical and environmental protection policy and associated physical and environmental protection controls are developed and documented;"},{"id":"pe-1_obj.a-4","label":"PE-01a.[04]","text":"the physical and environmental protection procedures are disseminated to {{ insert: param, pe-01_odp.02 }};"},{"id":"pe-1_obj.a.1.a-1","label":"PE-01a.01(a)[01]","text":"the {{ insert: param, pe-01_odp.03 }} physical and environmental protection policy addresses purpose;"},{"id":"pe-1_obj.a.1.a-2","label":"PE-01a.01(a)[02]","text":"the {{ insert: param, pe-01_odp.03 }} physical and environmental protection policy addresses scope;"},{"id":"pe-1_obj.a.1.a-3","label":"PE-01a.01(a)[03]","text":"the {{ insert: param, pe-01_odp.03 }} physical and environmental protection policy addresses roles;"},{"id":"pe-1_obj.a.1.a-4","label":"PE-01a.01(a)[04]","text":"the {{ insert: param, pe-01_odp.03 }} physical and environmental protection policy addresses responsibilities;"},{"id":"pe-1_obj.a.1.a-5","label":"PE-01a.01(a)[05]","text":"the {{ insert: param, pe-01_odp.03 }} physical and environmental protection policy addresses management commitment;"},{"id":"pe-1_obj.a.1.a-6","label":"PE-01a.01(a)[06]","text":"the {{ insert: param, pe-01_odp.03 }} physical and environmental protection policy addresses coordination among organizational entities;"},{"id":"pe-1_obj.a.1.a-7","label":"PE-01a.01(a)[07]","text":"the {{ insert: param, pe-01_odp.03 }} physical and environmental protection policy addresses compliance;"},{"id":"pe-1_obj.a.1.b","label":"PE-01a.01(b)","text":"the {{ insert: param, pe-01_odp.03 }} physical and environmental protection policy is consistent with applicable laws, Executive Orders, directives, regulations, policies, standards, and guidelines;"},{"id":"pe-1_obj.b","label":"PE-01b.","text":"the {{ insert: param, pe-01_odp.04 }} is designated to manage the development, documentation, and dissemination of the physical and environmental protection policy and procedures;"},{"id":"pe-1_obj.c.1-1","label":"PE-01c.01[01]","text":"the current physical and environmental protection policy is reviewed and updated {{ insert: param, pe-01_odp.05 }};"},{"id":"pe-1_obj.c.1-2","label":"PE-01c.01[02]","text":"the current physical and environmental protection policy is reviewed and updated following {{ insert: param, pe-01_odp.06 }};"},{"id":"pe-1_obj.c.2-1","label":"PE-01c.02[01]","text":"the current physical and environmental protection procedures are reviewed and updated {{ insert: param, pe-01_odp.07 }};"},{"id":"pe-1_obj.c.2-2","label":"PE-01c.02[02]","text":"the current physical and environmental protection procedures are reviewed and updated following {{ insert: param, pe-01_odp.08 }}."}],"methods":[{"method":"examine","label":"PE-01-Examine"},{"method":"interview","label":"PE-01-Interview"}],"references":[{"title":"SP 800-12"},{"title":"SP 800-30"},{"title":"SP 800-39"},{"title":"SP 800-100"}],"related_controls":["AT-3","PM-9","PS-8","SI-12"]},{"id":"PE-2","oscal_id":"pe-2","family":"PE","title":"Physical Access Authorizations","statement":"a. Develop, approve, and maintain a list of individuals with authorized access to the facility where the system resides;\nb. Issue authorization credentials for facility access;\nc. Review the access list detailing authorized facility access by individuals <frequency> ; and\nd. Remove individuals from the facility access list when access is no longer required.","supplemental_guidance":"Physical access authorizations apply to employees and visitors. Individuals with permanent physical access authorization credentials are not considered visitors. Authorization credentials include ID badges, identification cards, and smart cards. Organizations determine the strength of authorization credentials needed consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Physical access authorizations may not be necessary to access certain areas within facilities that are designated as publicly accessible.","implementation_level":"organization","parameters":[{"id":"pe-02_odp","label":"frequency"}],"objectives":[{"id":"pe-2_obj.a-1","label":"PE-02a.[01]","text":"a list of individuals with authorized access to the facility where the system resides has been developed;"},{"id":"pe-2_obj.a-2","label":"PE-02a.[02]","text":"the list of individuals with authorized access to the facility where the system resides has been approved;"},{"id":"pe-2_obj.a-3","label":"PE-02a.[03]","text":"the list of individuals with authorized access to the facility where the system resides has been maintained;"},{"id":"pe-2_obj.b","label":"PE-02b.","text":"authorization credentials are issued for facility access;"},{"id":"pe-2_obj.c","label":"PE-02c.","text":"the access list detailing authorized facility access by individuals is reviewed {{ insert: param, pe-02_odp }};"},{"id":"pe-2_obj.d","label":"PE-02d.","text":"individuals are removed from the facility access list when access is no longer required."}],"methods":[{"method":"examine","label":"PE-02-Examine"},{"method":"interview","label":"PE-02-Interview"},{"method":"test","label":"PE-02-Test"}],"references":[{"title":"FIPS 201-2"},{"title":"SP 800-73-4"},{"title":"SP 800-76-2"},{"title":"SP 800-78-4"}],"related_controls":["AT-3","AU-9","IA-4","MA-5","MP-2","PE-3","PE-4","PE-5","PE-8","PM-12","PS-3","PS-4","PS-5","PS-6"],"enhancements":[{"id":"PE-2(1)","oscal_id":"pe-2.1","family":"PE","title":"Access by Position or Role","statement":"Authorize physical access to the facility where the system resides based on position or role.","supplemental_guidance":"Role-based facility access includes access by authorized permanent and regular/routine maintenance personnel, duty officers, and emergency medical staff.","implementation_level":"organization","methods":[{"method":"examine","label":"PE-02(01)-Examine"},{"method":"interview","label":"PE-02(01)-Interview"},{"method":"test","label":"PE-02(01)-Test"}],"related_controls":["AC-2","AC-3","AC-6"],"is_enhancement":true,"parent_id":"PE-2"},{"id":"PE-2(2)","oscal_id":"pe-2.2","family":"PE","title":"Two Forms of Identification","statement":"Require two forms of identification from the following forms of identification for visitor access to the facility where the system resides: <list of acceptable forms of identification>.","supplemental_guidance":"Acceptable forms of identification include passports, REAL ID-compliant drivers’ licenses, and Personal Identity Verification (PIV) cards. For gaining access to facilities using automated mechanisms, organizations may use PIV cards, key cards, PINs, and biometrics.","implementation_level":"organization","parameters":[{"id":"pe-02.02_odp","label":"list of acceptable forms of identification"}],"methods":[{"method":"examine","label":"PE-02(02)-Examine"},{"method":"interview","label":"PE-02(02)-Interview"},{"method":"test","label":"PE-02(02)-Test"}],"related_controls":["IA-2","IA-4","IA-5"],"is_enhancement":true,"parent_id":"PE-2"},{"id":"PE-2(3)","oscal_id":"pe-2.3","family":"PE","title":"Restrict Unescorted Access","statement":"Restrict unescorted access to the facility where the system resides to personnel with <organization-defined parameter>.","supplemental_guidance":"Individuals without required security clearances, access approvals, or need to know are escorted by individuals with appropriate physical access authorizations to ensure that information is not exposed or otherwise compromised.","implementation_level":"organization","parameters":[{"id":"pe-02.03_odp.01","label":"","choices":["security clearances for all information contained within the system","formal access authorizations for all information contained within the system","need for access to all information contained within the system","{{ insert: param, pe-02.03_odp.02 }} "],"how_many":"one-or-more"},{"id":"pe-02.03_odp.02","label":"physical access authorizations"}],"methods":[{"method":"examine","label":"PE-02(03)-Examine"},{"method":"interview","label":"PE-02(03)-Interview"},{"method":"test","label":"PE-02(03)-Test"}],"related_controls":["PS-2","PS-6"],"is_enhancement":true,"parent_id":"PE-2"}]},{"id":"PE-3","oscal_id":"pe-3","family":"PE","title":"Physical Access Control","statement":"a. Enforce physical access authorizations at <entry and exit points> by:\n  Enforce physical access authorizations at <entry and exit points> by:\n  1. Verifying individual access authorizations before granting access to the facility; and\n  2. Controlling ingress and egress to the facility using <organization-defined parameter>;\nb. Maintain physical access audit logs for <entry or exit points>;\nc. Control access to areas within the facility designated as publicly accessible by implementing the following controls: <physical access controls>;\nd. Escort visitors and control visitor activity <circumstances>;\ne. Secure keys, combinations, and other physical access devices;\nf. Inventory <physical access devices> every <frequency> ; and\ng. Change combinations and keys <organization-defined frequency> and/or when keys are lost, combinations are compromised, or when individuals possessing the keys or combinations are transferred or terminated.","supplemental_guidance":"Physical access control applies to employees and visitors. Individuals with permanent physical access authorizations are not considered visitors. Physical access controls for publicly accessible areas may include physical access control logs/records, guards, or physical access devices and barriers to prevent movement from publicly accessible areas to non-public areas. Organizations determine the types of guards needed, including professional security staff, system users, or administrative staff. Physical access devices include keys, locks, combinations, biometric readers, and card readers. Physical access control systems comply with applicable laws, executive orders, directives, policies, regulations, standards, and guidelines. Organizations have flexibility in the types of audit logs employed. Audit logs can be procedural, automated, or some combination thereof. Physical access points can include facility access points, interior access points to systems that require supplemental access controls, or both. Components of systems may be in areas designated as publicly accessible with organizations controlling access to the components.","implementation_level":"organization","parameters":[{"id":"pe-3_prm_9","label":"organization-defined frequency"},{"id":"pe-03_odp.01","label":"entry and exit points"},{"id":"pe-03_odp.02","label":"","choices":["{{ insert: param, pe-03_odp.03 }} ","guards"],"how_many":"one-or-more"},{"id":"pe-03_odp.03","label":"systems or devices"},{"id":"pe-03_odp.04","label":"entry or exit points"},{"id":"pe-03_odp.05","label":"physical access controls"},{"id":"pe-03_odp.06","label":"circumstances"},{"id":"pe-03_odp.07","label":"physical access devices"},{"id":"pe-03_odp.08","label":"frequency"},{"id":"pe-03_odp.09","label":"frequency"},{"id":"pe-03_odp.10","label":"frequency"}],"objectives":[{"id":"pe-3_obj.a.1","label":"PE-03a.01","text":"physical access authorizations are enforced at {{ insert: param, pe-03_odp.01 }} by verifying individual access authorizations before granting access to the facility;"},{"id":"pe-3_obj.a.2","label":"PE-03a.02","text":"physical access authorizations are enforced at {{ insert: param, pe-03_odp.01 }} by controlling ingress and egress to the facility using {{ insert: param, pe-03_odp.02 }};"},{"id":"pe-3_obj.b","label":"PE-03b.","text":"physical access audit logs are maintained for {{ insert: param, pe-03_odp.04 }};"},{"id":"pe-3_obj.c","label":"PE-03c.","text":"access to areas within the facility designated as publicly accessible are maintained by implementing {{ insert: param, pe-03_odp.05 }};"},{"id":"pe-3_obj.d-1","label":"PE-03d.[01]","text":"visitors are escorted;"},{"id":"pe-3_obj.d-2","label":"PE-03d.[02]","text":"visitor activity is controlled {{ insert: param, pe-03_odp.06 }};"},{"id":"pe-3_obj.e-1","label":"PE-03e.[01]","text":"keys are secured;"},{"id":"pe-3_obj.e-2","label":"PE-03e.[02]","text":"combinations are secured;"},{"id":"pe-3_obj.e-3","label":"PE-03e.[03]","text":"other physical access devices are secured;"},{"id":"pe-3_obj.f","label":"PE-03f.","text":"{{ insert: param, pe-03_odp.07 }} are inventoried {{ insert: param, pe-03_odp.08 }};"},{"id":"pe-3_obj.g-1","label":"PE-03g.[01]","text":"combinations are changed {{ insert: param, pe-03_odp.09 }} , when combinations are compromised, or when individuals possessing the combinations are transferred or terminated;"},{"id":"pe-3_obj.g-2","label":"PE-03g.[02]","text":"keys are changed {{ insert: param, pe-03_odp.10 }} , when keys are lost, or when individuals possessing the keys are transferred or terminated."}],"methods":[{"method":"examine","label":"PE-03-Examine"},{"method":"interview","label":"PE-03-Interview"},{"method":"test","label":"PE-03-Test"}],"references":[{"title":"FIPS 201-2"},{"title":"SP 800-73-4"},{"title":"SP 800-76-2"},{"title":"SP 800-78-4"},{"title":"SP 800-116"}],"related_controls":["AT-3","AU-2","AU-6","AU-9","AU-13","CP-10","IA-3","IA-8","MA-5","MP-2","MP-4","PE-2","PE-4","PE-5","PE-8","PS-2","PS-3","PS-6","PS-7","RA-3","SC-28","SI-4","SR-3"],"enhancements":[{"id":"PE-3(1)","oscal_id":"pe-3.1","family":"PE","title":"System Access","statement":"Enforce physical access authorizations to the system in addition to the physical access controls for the facility at <physical spaces>.","supplemental_guidance":"Control of physical access to the system provides additional physical security for those areas within facilities where there is a concentration of system components.","implementation_level":"organization","parameters":[{"id":"pe-03.01_odp","label":"physical spaces"}],"objectives":[{"id":"pe-3.1_obj-1","label":"PE-03(01)[01]","text":"physical access authorizations to the system are enforced;"},{"id":"pe-3.1_obj.2","label":"PE-03(01)[02]","text":"physical access controls are enforced for the facility at {{ insert: param, pe-03.01_odp }}."}],"methods":[{"method":"examine","label":"PE-03(01)-Examine"},{"method":"interview","label":"PE-03(01)-Interview"},{"method":"test","label":"PE-03(01)-Test"}],"is_enhancement":true,"parent_id":"PE-3"},{"id":"PE-3(2)","oscal_id":"pe-3.2","family":"PE","title":"Facility and Systems","statement":"Perform security checks <frequency> at the physical perimeter of the facility or system for exfiltration of information or removal of system components.","supplemental_guidance":"Organizations determine the extent, frequency, and/or randomness of security checks to adequately mitigate risk associated with exfiltration.","implementation_level":"organization","parameters":[{"id":"pe-03.02_odp","label":"frequency"}],"methods":[{"method":"examine","label":"PE-03(02)-Examine"},{"method":"interview","label":"PE-03(02)-Interview"},{"method":"test","label":"PE-03(02)-Test"}],"related_controls":["AC-4","SC-7"],"is_enhancement":true,"parent_id":"PE-3"},{"id":"PE-3(3)","oscal_id":"pe-3.3","family":"PE","title":"Continuous Guards","statement":"Employ guards to control <physical access points> to the facility where the system resides 24 hours per day, 7 days per week.","supplemental_guidance":"Employing guards at selected physical access points to the facility provides a more rapid response capability for organizations. Guards also provide the opportunity for human surveillance in areas of the facility not covered by video surveillance.","implementation_level":"organization","parameters":[{"id":"pe-03.03_odp","label":"physical access points"}],"methods":[{"method":"examine","label":"PE-03(03)-Examine"},{"method":"interview","label":"PE-03(03)-Interview"},{"method":"test","label":"PE-03(03)-Test"}],"related_controls":["CP-6","CP-7","PE-6"],"is_enhancement":true,"parent_id":"PE-3"},{"id":"PE-3(4)","oscal_id":"pe-3.4","family":"PE","title":"Lockable Casings","statement":"Use lockable physical casings to protect <system components> from unauthorized physical access.","supplemental_guidance":"The greatest risk from the use of portable devices—such as smart phones, tablets, and notebook computers—is theft. Organizations can employ lockable, physical casings to reduce or eliminate the risk of equipment theft. Such casings come in a variety of sizes, from units that protect a single notebook computer to full cabinets that can protect multiple servers, computers, and peripherals. Lockable physical casings can be used in conjunction with cable locks or lockdown plates to prevent the theft of the locked casing containing the computer equipment.","implementation_level":"organization","parameters":[{"id":"pe-03.04_odp","label":"system components"}],"methods":[{"method":"examine","label":"PE-03(04)-Examine"},{"method":"interview","label":"PE-03(04)-Interview"},{"method":"test","label":"PE-03(04)-Test"}],"is_enhancement":true,"parent_id":"PE-3"},{"id":"PE-3(5)","oscal_id":"pe-3.5","family":"PE","title":"Tamper Protection","statement":"Employ <anti-tamper technologies> to <organization-defined parameter> physical tampering or alteration of <hardware components> within the system.","supplemental_guidance":"Organizations can implement tamper detection and prevention at selected hardware components or implement tamper detection at some components and tamper prevention at other components. Detection and prevention activities can employ many types of anti-tamper technologies, including tamper-detection seals and anti-tamper coatings. Anti-tamper programs help to detect hardware alterations through counterfeiting and other supply chain-related risks.","implementation_level":"organization","parameters":[{"id":"pe-03.05_odp.01","label":"anti-tamper technologies"},{"id":"pe-03.05_odp.02","label":"","choices":["detect","prevent"],"how_many":"one-or-more"},{"id":"pe-03.05_odp.03","label":"hardware components"}],"methods":[{"method":"examine","label":"PE-03(05)-Examine"},{"method":"interview","label":"PE-03(05)-Interview"},{"method":"test","label":"PE-03(05)-Test"}],"related_controls":["SA-16","SR-9","SR-11"],"is_enhancement":true,"parent_id":"PE-3"},{"id":"PE-3(6)","oscal_id":"pe-3.6","family":"PE","title":"Facility Penetration Testing","statement":"","is_enhancement":true,"parent_id":"PE-3"},{"id":"PE-3(7)","oscal_id":"pe-3.7","family":"PE","title":"Physical Barriers","statement":"Limit access using physical barriers.","supplemental_guidance":"Physical barriers include bollards, concrete slabs, jersey walls, and hydraulic active vehicle barriers.","implementation_level":"organization","methods":[{"method":"examine","label":"PE-03(07)-Examine"},{"method":"interview","label":"PE-03(07)-Interview"}],"is_enhancement":true,"parent_id":"PE-3"},{"id":"PE-3(8)","oscal_id":"pe-3.8","family":"PE","title":"Access Control Vestibules","statement":"Employ access control vestibules at <locations>.","supplemental_guidance":"An access control vestibule is part of a physical access control system that typically provides a space between two sets of interlocking doors. Vestibules are designed to prevent unauthorized individuals from following authorized individuals into facilities with controlled access. This activity, also known as piggybacking or tailgating, results in unauthorized access to the facility. Interlocking door controllers can be used to limit the number of individuals who enter controlled access points and to provide containment areas while authorization for physical access is verified. Interlocking door controllers can be fully automated (i.e., controlling the opening and closing of the doors) or partially automated (i.e., using security guards to control the number of individuals entering the containment area).","implementation_level":"organization","parameters":[{"id":"pe-03.08_odp","label":"locations"}],"methods":[{"method":"examine","label":"PE-03(08)-Examine"},{"method":"interview","label":"PE-03(08)-Interview"},{"method":"test","label":"PE-03(08)-Test"}],"is_enhancement":true,"parent_id":"PE-3"}]},{"id":"PE-4","oscal_id":"pe-4","family":"PE","title":"Access Control for Transmission","statement":"Control physical access to <system distribution and transmission lines> within organizational facilities using <security controls>.","supplemental_guidance":"Security controls applied to system distribution and transmission lines prevent accidental damage, disruption, and physical tampering. Such controls may also be necessary to prevent eavesdropping or modification of unencrypted transmissions. Security controls used to control physical access to system distribution and transmission lines include disconnected or locked spare jacks, locked wiring closets, protection of cabling by conduit or cable trays, and wiretapping sensors.","implementation_level":"organization","parameters":[{"id":"pe-04_odp.01","label":"system distribution and transmission lines"},{"id":"pe-04_odp.02","label":"security controls"}],"methods":[{"method":"examine","label":"PE-04-Examine"},{"method":"interview","label":"PE-04-Interview"},{"method":"test","label":"PE-04-Test"}],"related_controls":["AT-3","IA-4","MP-2","MP-4","PE-2","PE-3","PE-5","PE-9","SC-7","SC-8"]},{"id":"PE-5","oscal_id":"pe-5","family":"PE","title":"Access Control for Output Devices","statement":"Control physical access to output from <output devices> to prevent unauthorized individuals from obtaining the output.","supplemental_guidance":"Controlling physical access to output devices includes placing output devices in locked rooms or other secured areas with keypad or card reader access controls and allowing access to authorized individuals only, placing output devices in locations that can be monitored by personnel, installing monitor or screen filters, and using headphones. Examples of output devices include monitors, printers, scanners, audio devices, facsimile machines, and copiers.","implementation_level":"organization","parameters":[{"id":"pe-05_odp","label":"output devices"}],"methods":[{"method":"examine","label":"PE-05-Examine"},{"method":"interview","label":"PE-05-Interview"},{"method":"test","label":"PE-05-Test"}],"references":[{"title":"IR 8023"}],"related_controls":["PE-2","PE-3","PE-4","PE-18"],"enhancements":[{"id":"PE-5(1)","oscal_id":"pe-5.1","family":"PE","title":"Access to Output by Authorized Individuals","statement":"","is_enhancement":true,"parent_id":"PE-5"},{"id":"PE-5(2)","oscal_id":"pe-5.2","family":"PE","title":"Link to Individual Identity","statement":"Link individual identity to receipt of output from output devices.","supplemental_guidance":"Methods for linking individual identity to the receipt of output from output devices include installing security functionality on facsimile machines, copiers, and printers. Such functionality allows organizations to implement authentication on output devices prior to the release of output to individuals.","implementation_level":"system","methods":[{"method":"examine","label":"PE-05(02)-Examine"},{"method":"interview","label":"PE-05(02)-Interview"},{"method":"test","label":"PE-05(02)-Test"}],"is_enhancement":true,"parent_id":"PE-5"},{"id":"PE-5(3)","oscal_id":"pe-5.3","family":"PE","title":"Marking Output Devices","statement":"","is_enhancement":true,"parent_id":"PE-5"}]},{"id":"PE-6","oscal_id":"pe-6","family":"PE","title":"Monitoring Physical Access","statement":"a. Monitor physical access to the facility where the system resides to detect and respond to physical security incidents;\nb. Review physical access logs <frequency> and upon occurrence of <events> ; and\nc. Coordinate results of reviews and investigations with the organizational incident response capability.","supplemental_guidance":"Physical access monitoring includes publicly accessible areas within organizational facilities. Examples of physical access monitoring include the employment of guards, video surveillance equipment (i.e., cameras), and sensor devices. Reviewing physical access logs can help identify suspicious activity, anomalous events, or potential threats. The reviews can be supported by audit logging controls, such as [AU-2](#au-2) , if the access logs are part of an automated system. Organizational incident response capabilities include investigations of physical security incidents and responses to the incidents. Incidents include security violations or suspicious physical access activities. Suspicious physical access activities include accesses outside of normal work hours, repeated accesses to areas not normally accessed, accesses for unusual lengths of time, and out-of-sequence accesses.","implementation_level":"organization","parameters":[{"id":"pe-06_odp.01","label":"frequency"},{"id":"pe-06_odp.02","label":"events"}],"objectives":[{"id":"pe-6_obj.a","label":"PE-06a.","text":"physical access to the facility where the system resides is monitored to detect and respond to physical security incidents;"},{"id":"pe-6_obj.b-1","label":"PE-06b.[01]","text":"physical access logs are reviewed {{ insert: param, pe-06_odp.01 }};"},{"id":"pe-6_obj.b-2","label":"PE-06b.[02]","text":"physical access logs are reviewed upon occurrence of {{ insert: param, pe-06_odp.02 }};"},{"id":"pe-6_obj.c-1","label":"PE-06c.[01]","text":"results of reviews are coordinated with organizational incident response capabilities;"},{"id":"pe-6_obj.c-2","label":"PE-06c.[02]","text":"results of investigations are coordinated with organizational incident response capabilities."}],"methods":[{"method":"examine","label":"PE-06-Examine"},{"method":"interview","label":"PE-06-Interview"},{"method":"test","label":"PE-06-Test"}],"related_controls":["AU-2","AU-6","AU-9","AU-12","CA-7","CP-10","IR-4","IR-8"],"enhancements":[{"id":"PE-6(1)","oscal_id":"pe-6.1","family":"PE","title":"Intrusion Alarms and Surveillance Equipment","statement":"Monitor physical access to the facility where the system resides using physical intrusion alarms and surveillance equipment.","supplemental_guidance":"Physical intrusion alarms can be employed to alert security personnel when unauthorized access to the facility is attempted. Alarm systems work in conjunction with physical barriers, physical access control systems, and security guards by triggering a response when these other forms of security have been compromised or breached. Physical intrusion alarms can include different types of sensor devices, such as motion sensors, contact sensors, and broken glass sensors. Surveillance equipment includes video cameras installed at strategic locations throughout the facility.","implementation_level":"organization","objectives":[{"id":"pe-6.1_obj-1","label":"PE-06(01)[01]","text":"physical access to the facility where the system resides is monitored using physical intrusion alarms;"},{"id":"pe-6.1_obj-2","label":"PE-06(01)[02]","text":"physical access to the facility where the system resides is monitored using physical surveillance equipment."}],"methods":[{"method":"examine","label":"PE-06(01)-Examine"},{"method":"interview","label":"PE-06(01)-Interview"},{"method":"test","label":"PE-06(01)-Test"}],"is_enhancement":true,"parent_id":"PE-6"},{"id":"PE-6(2)","oscal_id":"pe-6.2","family":"PE","title":"Automated Intrusion Recognition and Responses","statement":"Recognize <classes or types of intrusions> and initiate <response actions> using <automated mechanisms>.","supplemental_guidance":"Response actions can include notifying selected organizational personnel or law enforcement personnel. Automated mechanisms implemented to initiate response actions include system alert notifications, email and text messages, and activating door locking mechanisms. Physical access monitoring can be coordinated with intrusion detection systems and system monitoring capabilities to provide integrated threat coverage for the organization.","implementation_level":"organization","parameters":[{"id":"pe-06.02_odp.01","label":"classes or types of intrusions"},{"id":"pe-06.02_odp.02","label":"response actions"},{"id":"pe-06.02_odp.03","label":"automated mechanisms"}],"objectives":[{"id":"pe-6.2_obj-1","label":"PE-06(02)[01]","text":"{{ insert: param, pe-06.02_odp.01 }} are recognized;"},{"id":"pe-6.2_obj-2","label":"PE-06(02)[02]","text":"{{ insert: param, pe-06.02_odp.02 }} are initiated using {{ insert: param, pe-06.02_odp.03 }}."}],"methods":[{"method":"examine","label":"PE-06(02)-Examine"},{"method":"interview","label":"PE-06(02)-Interview"},{"method":"test","label":"PE-06(02)-Test"}],"related_controls":["SI-4"],"is_enhancement":true,"parent_id":"PE-6"},{"id":"PE-6(3)","oscal_id":"pe-6.3","family":"PE","title":"Video Surveillance","statement":"(a) Employ video surveillance of <operational areas>;\n(b) Review video recordings <frequency> ; and\n(c) Retain video recordings for <time period>.","supplemental_guidance":"Video surveillance focuses on recording activity in specified areas for the purposes of subsequent review, if circumstances so warrant. Video recordings are typically reviewed to detect anomalous events or incidents. Monitoring the surveillance video is not required, although organizations may choose to do so. There may be legal considerations when performing and retaining video surveillance, especially if such surveillance is in a public location.","implementation_level":"organization","parameters":[{"id":"pe-06.03_odp.01","label":"operational areas"},{"id":"pe-06.03_odp.02","label":"frequency"},{"id":"pe-06.03_odp.03","label":"time period"}],"objectives":[{"id":"pe-6.3_obj.a","label":"PE-06(03)(a)","text":"video surveillance of {{ insert: param, pe-06.03_odp.01 }} is employed;"},{"id":"pe-6.3_obj.b","label":"PE-06(03)(b)","text":"video recordings are reviewed {{ insert: param, pe-06.03_odp.02 }};"},{"id":"pe-6.3_obj.c","label":"PE-06(03)(c)","text":"video recordings are retained for {{ insert: param, pe-06.03_odp.03 }}."}],"methods":[{"method":"examine","label":"PE-06(03)-Examine"},{"method":"interview","label":"PE-06(03)-Interview"},{"method":"test","label":"PE-06(03)-Test"}],"is_enhancement":true,"parent_id":"PE-6"},{"id":"PE-6(4)","oscal_id":"pe-6.4","family":"PE","title":"Monitoring Physical Access to Systems","statement":"Monitor physical access to the system in addition to the physical access monitoring of the facility at <physical spaces>.","supplemental_guidance":"Monitoring physical access to systems provides additional monitoring for those areas within facilities where there is a concentration of system components, including server rooms, media storage areas, and communications centers. Physical access monitoring can be coordinated with intrusion detection systems and system monitoring capabilities to provide comprehensive and integrated threat coverage for the organization.","implementation_level":"organization","parameters":[{"id":"pe-06.04_odp","label":"physical spaces"}],"methods":[{"method":"examine","label":"PE-06(04)-Examine"},{"method":"interview","label":"PE-06(04)-Interview"},{"method":"test","label":"PE-06(04)-Test"}],"is_enhancement":true,"parent_id":"PE-6"}]},{"id":"PE-7","oscal_id":"pe-7","family":"PE","title":"Visitor Control","statement":""},{"id":"PE-8","oscal_id":"pe-8","family":"PE","title":"Visitor Access Records","statement":"a. Maintain visitor access records to the facility where the system resides for <time period>;\nb. Review visitor access records <frequency> ; and\nc. Report anomalies in visitor access records to <personnel>.","supplemental_guidance":"Visitor access records include the names and organizations of individuals visiting, visitor signatures, forms of identification, dates of access, entry and departure times, purpose of visits, and the names and organizations of individuals visited. Access record reviews determine if access authorizations are current and are still required to support organizational mission and business functions. Access records are not required for publicly accessible areas.","implementation_level":"organization","parameters":[{"id":"pe-08_odp.01","label":"time period"},{"id":"pe-08_odp.02","label":"frequency"},{"id":"pe-08_odp.03","label":"personnel"}],"objectives":[{"id":"pe-8_obj.a","label":"PE-08a.","text":"visitor access records for the facility where the system resides are maintained for {{ insert: param, pe-08_odp.01 }};"},{"id":"pe-8_obj.b","label":"PE-08b.","text":"visitor access records are reviewed {{ insert: param, pe-08_odp.02 }};"},{"id":"pe-8_obj.c","label":"PE-08c.","text":"visitor access records anomalies are reported to {{ insert: param, pe-08_odp.03 }}."}],"methods":[{"method":"examine","label":"PE-08-Examine"},{"method":"interview","label":"PE-08-Interview"},{"method":"test","label":"PE-08-Test"}],"related_controls":["PE-2","PE-3","PE-6"],"enhancements":[{"id":"PE-8(1)","oscal_id":"pe-8.1","family":"PE","title":"Automated Records Maintenance and Review","statement":"Maintain and review visitor access records using <organization-defined automated mechanisms>.","supplemental_guidance":"Visitor access records may be stored and maintained in a database management system that is accessible by organizational personnel. Automated access to such records facilitates record reviews on a regular basis to determine if access authorizations are current and still required to support organizational mission and business functions.","implementation_level":"organization","parameters":[{"id":"pe-8.1_prm_1","label":"organization-defined automated mechanisms"},{"id":"pe-08.01_odp.01","label":"automated mechanisms"},{"id":"pe-08.01_odp.02","label":"automated mechanisms"}],"objectives":[{"id":"pe-8.1_obj-1","label":"PE-08(01)[01]","text":"visitor access records are maintained using {{ insert: param, pe-08.01_odp.01 }};"},{"id":"pe-8.1_obj-2","label":"PE-08(01)[02]","text":"visitor access records are reviewed using {{ insert: param, pe-08.01_odp.02 }}."}],"methods":[{"method":"examine","label":"PE-08(01)-Examine"},{"method":"interview","label":"PE-08(01)-Interview"},{"method":"test","label":"PE-08(01)-Test"}],"is_enhancement":true,"parent_id":"PE-8"},{"id":"PE-8(2)","oscal_id":"pe-8.2","family":"PE","title":"Physical Access Records","statement":"","is_enhancement":true,"parent_id":"PE-8"},{"id":"PE-8(3)","oscal_id":"pe-8.3","family":"PE","title":"Limit Personally Identifiable Information Elements","statement":"Limit personally identifiable information contained in visitor access records to the following elements identified in the privacy risk assessment: <elements>.","supplemental_guidance":"Organizations may have requirements that specify the contents of visitor access records. Limiting personally identifiable information in visitor access records when such information is not needed for operational purposes helps reduce the level of privacy risk created by a system.","implementation_level":"organization","parameters":[{"id":"pe-08.03_odp","label":"elements"}],"methods":[{"method":"examine","label":"PE-08(03)-Examine"},{"method":"interview","label":"PE-08(03)-Interview"},{"method":"test","label":"PE-08(03)-Test"}],"related_controls":["RA-3","SA-8"],"is_enhancement":true,"parent_id":"PE-8"}]},{"id":"PE-9","oscal_id":"pe-9","family":"PE","title":"Power Equipment and Cabling","statement":"Protect power equipment and power cabling for the system from damage and destruction.","supplemental_guidance":"Organizations determine the types of protection necessary for the power equipment and cabling employed at different locations that are both internal and external to organizational facilities and environments of operation. Types of power equipment and cabling include internal cabling and uninterruptable power sources in offices or data centers, generators and power cabling outside of buildings, and power sources for self-contained components such as satellites, vehicles, and other deployable systems.","implementation_level":"organization","objectives":[{"id":"pe-9_obj-1","label":"PE-09[01]","text":"power equipment for the system is protected from damage and destruction;"},{"id":"pe-9_obj-2","label":"PE-09[02]","text":"power cabling for the system is protected from damage and destruction."}],"methods":[{"method":"examine","label":"PE-09-Examine"},{"method":"interview","label":"PE-09-Interview"},{"method":"test","label":"PE-09-Test"}],"related_controls":["PE-4"],"enhancements":[{"id":"PE-9(1)","oscal_id":"pe-9.1","family":"PE","title":"Redundant Cabling","statement":"Employ redundant power cabling paths that are physically separated by <distance>.","supplemental_guidance":"Physically separate and redundant power cables ensure that power continues to flow in the event that one of the cables is cut or otherwise damaged.","implementation_level":"organization","parameters":[{"id":"pe-09.01_odp","label":"distance"}],"methods":[{"method":"examine","label":"PE-09(01)-Examine"},{"method":"interview","label":"PE-09(01)-Interview"},{"method":"test","label":"PE-09(01)-Test"}],"is_enhancement":true,"parent_id":"PE-9"},{"id":"PE-9(2)","oscal_id":"pe-9.2","family":"PE","title":"Automatic Voltage Controls","statement":"Employ automatic voltage controls for <critical system components>.","supplemental_guidance":"Automatic voltage controls can monitor and control voltage. Such controls include voltage regulators, voltage conditioners, and voltage stabilizers.","implementation_level":"organization","parameters":[{"id":"pe-09.02_odp","label":"critical system components"}],"methods":[{"method":"examine","label":"PE-09(02)-Examine"},{"method":"interview","label":"PE-09(02)-Interview"},{"method":"test","label":"PE-09(02)-Test"}],"is_enhancement":true,"parent_id":"PE-9"}]},{"id":"PE-10","oscal_id":"pe-10","family":"PE","title":"Emergency Shutoff","statement":"a. Provide the capability of shutting off power to <system or individual system components> in emergency situations;\nb. Place emergency shutoff switches or devices in <location> to facilitate access for authorized personnel; and\nc. Protect emergency power shutoff capability from unauthorized activation.","supplemental_guidance":"Emergency power shutoff primarily applies to organizational facilities that contain concentrations of system resources, including data centers, mainframe computer rooms, server rooms, and areas with computer-controlled machinery.","implementation_level":"organization","parameters":[{"id":"pe-10_odp.01","label":"system or individual system components"},{"id":"pe-10_odp.02","label":"location"}],"objectives":[{"id":"pe-10_obj.a","label":"PE-10a.","text":"the capability to shut off power to {{ insert: param, pe-10_odp.01 }} in emergency situations is provided;"},{"id":"pe-10_obj.b","label":"PE-10b.","text":"emergency shutoff switches or devices are placed in {{ insert: param, pe-10_odp.02 }} to facilitate access for authorized personnel;"},{"id":"pe-10_obj.c","label":"PE-10c.","text":"the emergency power shutoff capability is protected from unauthorized activation."}],"methods":[{"method":"examine","label":"PE-10-Examine"},{"method":"interview","label":"PE-10-Interview"},{"method":"test","label":"PE-10-Test"}],"related_controls":["PE-15"],"enhancements":[{"id":"PE-10(1)","oscal_id":"pe-10.1","family":"PE","title":"Accidental and Unauthorized Activation","statement":"","is_enhancement":true,"parent_id":"PE-10"}]},{"id":"PE-11","oscal_id":"pe-11","family":"PE","title":"Emergency Power","statement":"Provide an uninterruptible power supply to facilitate <organization-defined parameter> in the event of a primary power source loss.","supplemental_guidance":"An uninterruptible power supply (UPS) is an electrical system or mechanism that provides emergency power when there is a failure of the main power source. A UPS is typically used to protect computers, data centers, telecommunication equipment, or other electrical equipment where an unexpected power disruption could cause injuries, fatalities, serious mission or business disruption, or loss of data or information. A UPS differs from an emergency power system or backup generator in that the UPS provides near-instantaneous protection from unanticipated power interruptions from the main power source by providing energy stored in batteries, supercapacitors, or flywheels. The battery duration of a UPS is relatively short but provides sufficient time to start a standby power source, such as a backup generator, or properly shut down the system.","implementation_level":"organization","parameters":[{"id":"pe-11_odp","label":"","choices":["an orderly shutdown of the system","transition of the system to long-term alternate power"]}],"methods":[{"method":"examine","label":"PE-11-Examine"},{"method":"interview","label":"PE-11-Interview"},{"method":"test","label":"PE-11-Test"}],"related_controls":["AT-3","CP-2","CP-7"],"enhancements":[{"id":"PE-11(1)","oscal_id":"pe-11.1","family":"PE","title":"Alternate Power Supply — Minimal Operational Capability","statement":"Provide an alternate power supply for the system that is activated <organization-defined parameter> and that can maintain minimally required operational capability in the event of an extended loss of the primary power source.","supplemental_guidance":"Provision of an alternate power supply with minimal operating capability can be satisfied by accessing a secondary commercial power supply or other external power supply.","implementation_level":"organization","parameters":[{"id":"pe-11.01_odp","label":"","choices":["manually","automatically"]}],"objectives":[{"id":"pe-11.1_obj-1","label":"PE-11(01)[01]","text":"an alternate power supply provided for the system is activated {{ insert: param, pe-11.01_odp }};"},{"id":"pe-11.1_obj-2","label":"PE-11(01)[02]","text":"the alternate power supply provided for the system can maintain minimally required operational capability in the event of an extended loss of the primary power source."}],"methods":[{"method":"examine","label":"PE-11(01)-Examine"},{"method":"interview","label":"PE-11(01)-Interview"},{"method":"test","label":"PE-11(01)-Test"}],"is_enhancement":true,"parent_id":"PE-11"},{"id":"PE-11(2)","oscal_id":"pe-11.2","family":"PE","title":"Alternate Power Supply — Self-contained","statement":"Provide an alternate power supply for the system that is activated <organization-defined parameter> and that is:\n(a) Self-contained;\n(b) Not reliant on external power generation; and\n(c) Capable of maintaining <organization-defined parameter> in the event of an extended loss of the primary power source.","supplemental_guidance":"The provision of a long-term, self-contained power supply can be satisfied by using one or more generators with sufficient capacity to meet the needs of the organization.","implementation_level":"organization","parameters":[{"id":"pe-11.02_odp.01","label":"","choices":["manually","automatically"]},{"id":"pe-11.02_odp.02","label":"","choices":["minimally required operational capability","full operational capability"]}],"objectives":[{"id":"pe-11.2_obj.a","label":"PE-11(02)(a)","text":"the alternate power supply provided for the system is self-contained;"},{"id":"pe-11.2_obj.b","label":"PE-11(02)(b)","text":"the alternate power supply provided for the system is not reliant on external power generation;"},{"id":"pe-11.2_obj.c","label":"PE-11(02)(c)","text":"the alternate power supply provided for the system is capable of maintaining {{ insert: param, pe-11.02_odp.02 }} in the event of an extended loss of the primary power source."}],"methods":[{"method":"examine","label":"PE-11(02)-Examine"},{"method":"interview","label":"PE-11(02)-Interview"},{"method":"test","label":"PE-11(02)-Test"}],"is_enhancement":true,"parent_id":"PE-11"}]},{"id":"PE-12","oscal_id":"pe-12","family":"PE","title":"Emergency Lighting","statement":"Employ and maintain automatic emergency lighting for the system that activates in the event of a power outage or disruption and that covers emergency exits and evacuation routes within the facility.","supplemental_guidance":"The provision of emergency lighting applies primarily to organizational facilities that contain concentrations of system resources, including data centers, server rooms, and mainframe computer rooms. Emergency lighting provisions for the system are described in the contingency plan for the organization. If emergency lighting for the system fails or cannot be provided, organizations consider alternate processing sites for power-related contingencies.","implementation_level":"organization","objectives":[{"id":"pe-12_obj-1","label":"PE-12[01]","text":"automatic emergency lighting that activates in the event of a power outage or disruption is employed for the system;"},{"id":"pe-12_obj-2","label":"PE-12[02]","text":"automatic emergency lighting that activates in the event of a power outage or disruption is maintained for the system;"},{"id":"pe-12_obj-3","label":"PE-12[03]","text":"automatic emergency lighting for the system covers emergency exits within the facility;"},{"id":"pe-12_obj-4","label":"PE-12[04]","text":"automatic emergency lighting for the system covers evacuation routes within the facility."}],"methods":[{"method":"examine","label":"PE-12-Examine"},{"method":"interview","label":"PE-12-Interview"},{"method":"test","label":"PE-12-Test"}],"related_controls":["CP-2","CP-7"],"enhancements":[{"id":"PE-12(1)","oscal_id":"pe-12.1","family":"PE","title":"Essential Mission and Business Functions","statement":"Provide emergency lighting for all areas within the facility supporting essential mission and business functions.","supplemental_guidance":"Organizations define their essential missions and functions.","implementation_level":"organization","methods":[{"method":"examine","label":"PE-12(01)-Examine"},{"method":"interview","label":"PE-12(01)-Interview"},{"method":"test","label":"PE-12(01)-Test"}],"is_enhancement":true,"parent_id":"PE-12"}]},{"id":"PE-13","oscal_id":"pe-13","family":"PE","title":"Fire Protection","statement":"Employ and maintain fire detection and suppression systems that are supported by an independent energy source.","supplemental_guidance":"The provision of fire detection and suppression systems applies primarily to organizational facilities that contain concentrations of system resources, including data centers, server rooms, and mainframe computer rooms. Fire detection and suppression systems that may require an independent energy source include sprinkler systems and smoke detectors. An independent energy source is an energy source, such as a microgrid, that is separate, or can be separated, from the energy sources providing power for the other parts of the facility.","implementation_level":"organization","objectives":[{"id":"pe-13_obj-1","label":"PE-13[01]","text":"fire detection systems are employed;"},{"id":"pe-13_obj-2","label":"PE-13[02]","text":"employed fire detection systems are supported by an independent energy source;"},{"id":"pe-13_obj-3","label":"PE-13[03]","text":"employed fire detection systems are maintained;"},{"id":"pe-13_obj-4","label":"PE-13[04]","text":"fire suppression systems are employed;"},{"id":"pe-13_obj-5","label":"PE-13[05]","text":"employed fire suppression systems are supported by an independent energy source;"},{"id":"pe-13_obj-6","label":"PE-13[06]","text":"employed fire suppression systems are maintained."}],"methods":[{"method":"examine","label":"PE-13-Examine"},{"method":"interview","label":"PE-13-Interview"},{"method":"test","label":"PE-13-Test"}],"related_controls":["AT-3"],"enhancements":[{"id":"PE-13(1)","oscal_id":"pe-13.1","family":"PE","title":"Detection Systems — Automatic Activation and Notification","statement":"Employ fire detection systems that activate automatically and notify <personnel or roles> and <emergency responders> in the event of a fire.","supplemental_guidance":"Organizations can identify personnel, roles, and emergency responders if individuals on the notification list need to have access authorizations or clearances (e.g., to enter to facilities where access is restricted due to the classification or impact level of information within the facility). Notification mechanisms may require independent energy sources to ensure that the notification capability is not adversely affected by the fire.","implementation_level":"organization","parameters":[{"id":"pe-13.01_odp.01","label":"personnel or roles"},{"id":"pe-13.01_odp.02","label":"emergency responders"}],"objectives":[{"id":"pe-13.1_obj-1","label":"PE-13(01)[01]","text":"fire detection systems that activate automatically are employed in the event of a fire;"},{"id":"pe-13.1_obj-2","label":"PE-13(01)[02]","text":"fire detection systems that notify {{ insert: param, pe-13.01_odp.01 }} automatically are employed in the event of a fire;"},{"id":"pe-13.1_obj-3","label":"PE-13(01)[03]","text":"fire detection systems that notify {{ insert: param, pe-13.01_odp.02 }} automatically are employed in the event of a fire."}],"methods":[{"method":"examine","label":"PE-13(01)-Examine"},{"method":"interview","label":"PE-13(01)-Interview"},{"method":"test","label":"PE-13(01)-Test"}],"is_enhancement":true,"parent_id":"PE-13"},{"id":"PE-13(2)","oscal_id":"pe-13.2","family":"PE","title":"Suppression Systems — Automatic Activation and Notification","statement":"(a) Employ fire suppression systems that activate automatically and notify <personnel or roles> and <emergency responders> ; and\n(b) Employ an automatic fire suppression capability when the facility is not staffed on a continuous basis.","supplemental_guidance":"Organizations can identify specific personnel, roles, and emergency responders if individuals on the notification list need to have appropriate access authorizations and/or clearances (e.g., to enter to facilities where access is restricted due to the impact level or classification of information within the facility). Notification mechanisms may require independent energy sources to ensure that the notification capability is not adversely affected by the fire.","implementation_level":"organization","parameters":[{"id":"pe-13.02_odp.01","label":"personnel or roles"},{"id":"pe-13.02_odp.02","label":"emergency responders"}],"objectives":[{"id":"pe-13.2_obj.a-1","label":"PE-13(02)(a)[01]","text":"fire suppression systems that activate automatically are employed;"},{"id":"pe-13.2_obj.a-2","label":"PE-13(02)(a)[02]","text":"fire suppression systems that notify {{ insert: param, pe-13.02_odp.01 }} automatically are employed;"},{"id":"pe-13.2_obj.a-3","label":"PE-13(02)(a)[03]","text":"fire suppression systems that notify {{ insert: param, pe-13.02_odp.02 }} automatically are employed;"},{"id":"pe-13.2_obj.b","label":"PE-13(02)(b)","text":"an automatic fire suppression capability is employed when the facility is not staffed on a continuous basis."}],"methods":[{"method":"examine","label":"PE-13(02)-Examine"},{"method":"interview","label":"PE-13(02)-Interview"},{"method":"test","label":"PE-13(02)-Test"}],"is_enhancement":true,"parent_id":"PE-13"},{"id":"PE-13(3)","oscal_id":"pe-13.3","family":"PE","title":"Automatic Fire Suppression","statement":"","is_enhancement":true,"parent_id":"PE-13"},{"id":"PE-13(4)","oscal_id":"pe-13.4","family":"PE","title":"Inspections","statement":"Ensure that the facility undergoes <frequency> fire protection inspections by authorized and qualified inspectors and identified deficiencies are resolved within <time period>.","supplemental_guidance":"Authorized and qualified personnel within the jurisdiction of the organization include state, county, and city fire inspectors and fire marshals. Organizations provide escorts during inspections in situations where the systems that reside within the facilities contain sensitive information.","implementation_level":"organization","parameters":[{"id":"pe-13.04_odp.01","label":"frequency"},{"id":"pe-13.04_odp.02","label":"time period"}],"objectives":[{"id":"pe-13.4_obj-1","label":"PE-13(04)[01]","text":"the facility undergoes fire protection inspections {{ insert: param, pe-13.04_odp.01 }} by authorized and qualified inspectors;"},{"id":"pe-13.4_obj-2","label":"PE-13(04)[02]","text":"the identified deficiencies from fire protection inspections are resolved within {{ insert: param, pe-13.04_odp.02 }}."}],"methods":[{"method":"examine","label":"PE-13(04)-Examine"},{"method":"interview","label":"PE-13(04)-Interview"}],"is_enhancement":true,"parent_id":"PE-13"}]},{"id":"PE-14","oscal_id":"pe-14","family":"PE","title":"Environmental Controls","statement":"a. Maintain <organization-defined parameter> levels within the facility where the system resides at <acceptable levels> ; and\nb. Monitor environmental control levels <frequency>.","supplemental_guidance":"The provision of environmental controls applies primarily to organizational facilities that contain concentrations of system resources (e.g., data centers, mainframe computer rooms, and server rooms). Insufficient environmental controls, especially in very harsh environments, can have a significant adverse impact on the availability of systems and system components that are needed to support organizational mission and business functions.","implementation_level":"organization","parameters":[{"id":"pe-14_odp.01","label":"","choices":["temperature","humidity","pressure","radiation","{{ insert: param, pe-14_odp.02 }} "],"how_many":"one-or-more"},{"id":"pe-14_odp.02","label":"environmental control"},{"id":"pe-14_odp.03","label":"acceptable levels"},{"id":"pe-14_odp.04","label":"frequency"}],"objectives":[{"id":"pe-14_obj.a","label":"PE-14a.","text":"{{ insert: param, pe-14_odp.01 }} levels are maintained at {{ insert: param, pe-14_odp.03 }} within the facility where the system resides;"},{"id":"pe-14_obj.b","label":"PE-14b.","text":"environmental control levels are monitored {{ insert: param, pe-14_odp.04 }}."}],"methods":[{"method":"examine","label":"PE-14-Examine"},{"method":"interview","label":"PE-14-Interview"},{"method":"test","label":"PE-14-Test"}],"related_controls":["AT-3","CP-2"],"enhancements":[{"id":"PE-14(1)","oscal_id":"pe-14.1","family":"PE","title":"Automatic Controls","statement":"Employ the following automatic environmental controls in the facility to prevent fluctuations potentially harmful to the system: <automatic environmental controls>.","supplemental_guidance":"The implementation of automatic environmental controls provides an immediate response to environmental conditions that can damage, degrade, or destroy organizational systems or systems components.","implementation_level":"organization","parameters":[{"id":"pe-14.01_odp","label":"automatic environmental controls"}],"methods":[{"method":"examine","label":"PE-14(01)-Examine"},{"method":"interview","label":"PE-14(01)-Interview"},{"method":"test","label":"PE-14(01)-Test"}],"is_enhancement":true,"parent_id":"PE-14"},{"id":"PE-14(2)","oscal_id":"pe-14.2","family":"PE","title":"Monitoring with Alarms and Notifications","statement":"Employ environmental control monitoring that provides an alarm or notification of changes potentially harmful to personnel or equipment to <personnel or roles>.","supplemental_guidance":"The alarm or notification may be an audible alarm or a visual message in real time to personnel or roles defined by the organization. Such alarms and notifications can help minimize harm to individuals and damage to organizational assets by facilitating a timely incident response.","implementation_level":"organization","parameters":[{"id":"pe-14.02_odp","label":"personnel or roles"}],"objectives":[{"id":"pe-14.2_obj-1","label":"PE-14(02)[01]","text":"environmental control monitoring is employed;"},{"id":"pe-14.2_obj-2","label":"PE-14(02)[02]","text":"the environmental control monitoring capability provides an alarm or notification to {{ insert: param, pe-14.02_odp }} when changes are potentially harmful to personnel or equipment."}],"methods":[{"method":"examine","label":"PE-14(02)-Examine"},{"method":"interview","label":"PE-14(02)-Interview"},{"method":"test","label":"PE-14(02)-Test"}],"is_enhancement":true,"parent_id":"PE-14"}]},{"id":"PE-15","oscal_id":"pe-15","family":"PE","title":"Water Damage Protection","statement":"Protect the system from damage resulting from water leakage by providing master shutoff or isolation valves that are accessible, working properly, and known to key personnel.","supplemental_guidance":"The provision of water damage protection primarily applies to organizational facilities that contain concentrations of system resources, including data centers, server rooms, and mainframe computer rooms. Isolation valves can be employed in addition to or in lieu of master shutoff valves to shut off water supplies in specific areas of concern without affecting entire organizations.","implementation_level":"organization","objectives":[{"id":"pe-15_obj-1","label":"PE-15[01]","text":"the system is protected from damage resulting from water leakage by providing master shutoff or isolation valves;"},{"id":"pe-15_obj-2","label":"PE-15[02]","text":"the master shutoff or isolation valves are accessible;"},{"id":"pe-15_obj-3","label":"PE-15[03]","text":"the master shutoff or isolation valves are working properly;"},{"id":"pe-15_obj-4","label":"PE-15[04]","text":"the master shutoff or isolation valves are known to key personnel."}],"methods":[{"method":"examine","label":"PE-15-Examine"},{"method":"interview","label":"PE-15-Interview"},{"method":"test","label":"PE-15-Test"}],"related_controls":["AT-3","PE-10"],"enhancements":[{"id":"PE-15(1)","oscal_id":"pe-15.1","family":"PE","title":"Automation Support","statement":"Detect the presence of water near the system and alert <personnel or roles> using <automated mechanisms>.","supplemental_guidance":"Automated mechanisms include notification systems, water detection sensors, and alarms.","implementation_level":"organization","parameters":[{"id":"pe-15.01_odp.01","label":"personnel or roles"},{"id":"pe-15.01_odp.02","label":"automated mechanisms"}],"objectives":[{"id":"pe-15.1_obj-1","label":"PE-15(01)[01]","text":"the presence of water near the system can be detected automatically;"},{"id":"pe-15.1_obj-2","label":"PE-15(01)[02]","text":"{{ insert: param, pe-15.01_odp.01 }} is/are alerted using {{ insert: param, pe-15.01_odp.02 }}."}],"methods":[{"method":"examine","label":"PE-15(01)-Examine"},{"method":"interview","label":"PE-15(01)-Interview"},{"method":"test","label":"PE-15(01)-Test"}],"is_enhancement":true,"parent_id":"PE-15"}]},{"id":"PE-16","oscal_id":"pe-16","family":"PE","title":"Delivery and Removal","statement":"a. Authorize and control <organization-defined types of system components> entering and exiting the facility; and\nb. Maintain records of the system components.","supplemental_guidance":"Enforcing authorizations for entry and exit of system components may require restricting access to delivery areas and isolating the areas from the system and media libraries.","implementation_level":"organization","parameters":[{"id":"pe-16_prm_1","label":"organization-defined types of system components"},{"id":"pe-16_odp.01","label":"types of system components"},{"id":"pe-16_odp.02","label":"types of system components"}],"objectives":[{"id":"pe-16_obj.a-1","label":"PE-16a.[01]","text":"{{ insert: param, pe-16_odp.01 }} are authorized when entering the facility;"},{"id":"pe-16_obj.a-2","label":"PE-16a.[02]","text":"{{ insert: param, pe-16_odp.01 }} are controlled when entering the facility;"},{"id":"pe-16_obj.a-3","label":"PE-16a.[03]","text":"{{ insert: param, pe-16_odp.02 }} are authorized when exiting the facility;"},{"id":"pe-16_obj.a-4","label":"PE-16a.[04]","text":"{{ insert: param, pe-16_odp.02 }} are controlled when exiting the facility;"},{"id":"pe-16_obj.b","label":"PE-16b.","text":"records of the system components are maintained."}],"methods":[{"method":"examine","label":"PE-16-Examine"},{"method":"interview","label":"PE-16-Interview"},{"method":"test","label":"PE-16-Test"}],"related_controls":["CM-3","CM-8","MA-2","MA-3","MP-5","PE-20","SR-2","SR-3","SR-4","SR-6"]},{"id":"PE-17","oscal_id":"pe-17","family":"PE","title":"Alternate Work Site","statement":"a. Determine and document the <alternate work sites> allowed for use by employees;\nb. Employ the following controls at alternate work sites: <controls>;\nc. Assess the effectiveness of controls at alternate work sites; and\nd. Provide a means for employees to communicate with information security and privacy personnel in case of incidents.","supplemental_guidance":"Alternate work sites include government facilities or the private residences of employees. While distinct from alternative processing sites, alternate work sites can provide readily available alternate locations during contingency operations. Organizations can define different sets of controls for specific alternate work sites or types of sites depending on the work-related activities conducted at the sites. Implementing and assessing the effectiveness of organization-defined controls and providing a means to communicate incidents at alternate work sites supports the contingency planning activities of organizations.","implementation_level":"organization","parameters":[{"id":"pe-17_odp.01","label":"alternate work sites"},{"id":"pe-17_odp.02","label":"controls"}],"objectives":[{"id":"pe-17_obj.a","label":"PE-17a.","text":"{{ insert: param, pe-17_odp.01 }} are determined and documented;"},{"id":"pe-17_obj.b","label":"PE-17b.","text":"{{ insert: param, pe-17_odp.02 }} are employed at alternate work sites;"},{"id":"pe-17_obj.c","label":"PE-17c.","text":"the effectiveness of controls at alternate work sites is assessed;"},{"id":"pe-17_obj.d","label":"PE-17d.","text":"a means for employees to communicate with information security and privacy personnel in case of incidents is provided."}],"methods":[{"method":"examine","label":"PE-17-Examine"},{"method":"interview","label":"PE-17-Interview"},{"method":"test","label":"PE-17-Test"}],"references":[{"title":"SP 800-46"}],"related_controls":["AC-17","AC-18","CP-7"]},{"id":"PE-18","oscal_id":"pe-18","family":"PE","title":"Location of System Components","statement":"Position system components within the facility to minimize potential damage from <physical and environmental hazards> and to minimize the opportunity for unauthorized access.","supplemental_guidance":"Physical and environmental hazards include floods, fires, tornadoes, earthquakes, hurricanes, terrorism, vandalism, an electromagnetic pulse, electrical interference, and other forms of incoming electromagnetic radiation. Organizations consider the location of entry points where unauthorized individuals, while not being granted access, might nonetheless be near systems. Such proximity can increase the risk of unauthorized access to organizational communications using wireless packet sniffers or microphones, or unauthorized disclosure of information.","implementation_level":"organization","parameters":[{"id":"pe-18_odp","label":"physical and environmental hazards"}],"methods":[{"method":"examine","label":"PE-18-Examine"},{"method":"interview","label":"PE-18-Interview"},{"method":"test","label":"PE-18-Test"}],"related_controls":["CP-2","PE-5","PE-19","PE-20","RA-3"],"enhancements":[{"id":"PE-18(1)","oscal_id":"pe-18.1","family":"PE","title":"Facility Site","statement":"","is_enhancement":true,"parent_id":"PE-18"}]},{"id":"PE-19","oscal_id":"pe-19","family":"PE","title":"Information Leakage","statement":"Protect the system from information leakage due to electromagnetic signals emanations.","supplemental_guidance":"Information leakage is the intentional or unintentional release of data or information to an untrusted environment from electromagnetic signals emanations. The security categories or classifications of systems (with respect to confidentiality), organizational security policies, and risk tolerance guide the selection of controls employed to protect systems against information leakage due to electromagnetic signals emanations.","implementation_level":"organization","methods":[{"method":"examine","label":"PE-19-Examine"},{"method":"interview","label":"PE-19-Interview"},{"method":"test","label":"PE-19-Test"}],"references":[{"title":"FIPS 199"}],"related_controls":["AC-18","PE-18","PE-20"],"enhancements":[{"id":"PE-19(1)","oscal_id":"pe-19.1","family":"PE","title":"National Emissions Policies and Procedures","statement":"Protect system components, associated data communications, and networks in accordance with national Emissions Security policies and procedures based on the security category or classification of the information.","supplemental_guidance":"Emissions Security (EMSEC) policies include the former TEMPEST policies.","implementation_level":"organization","objectives":[{"id":"pe-19.1_obj-1","label":"PE-19(01)[01]","text":"system components are protected in accordance with national emissions security policies and procedures based on the security category or classification of the information;"},{"id":"pe-19.1_obj-2","label":"PE-19(01)[02]","text":"associated data communications are protected in accordance with national emissions security policies and procedures based on the security category or classification of the information;"},{"id":"pe-19.1_obj-3","label":"PE-19(01)[03]","text":"networks are protected in accordance with national emissions security policies and procedures based on the security category or classification of the information."}],"methods":[{"method":"examine","label":"PE-19(01)-Examine"},{"method":"interview","label":"PE-19(01)-Interview"},{"method":"test","label":"PE-19(01)-Test"}],"is_enhancement":true,"parent_id":"PE-19"}]},{"id":"PE-20","oscal_id":"pe-20","family":"PE","title":"Asset Monitoring and Tracking","statement":"Employ <asset location technologies> to track and monitor the location and movement of <assets> within <controlled areas>.","supplemental_guidance":"Asset location technologies can help ensure that critical assets—including vehicles, equipment, and system components—remain in authorized locations. Organizations consult with the Office of the General Counsel and senior agency official for privacy regarding the deployment and use of asset location technologies to address potential privacy concerns.","implementation_level":"organization","parameters":[{"id":"pe-20_odp.01","label":"asset location technologies"},{"id":"pe-20_odp.02","label":"assets"},{"id":"pe-20_odp.03","label":"controlled areas"}],"methods":[{"method":"examine","label":"PE-20-Examine"},{"method":"interview","label":"PE-20-Interview"},{"method":"test","label":"PE-20-Test"}],"related_controls":["CM-8","PE-16","PM-8"]},{"id":"PE-21","oscal_id":"pe-21","family":"PE","title":"Electromagnetic Pulse Protection","statement":"Employ <protective measures> against electromagnetic pulse damage for <system and system components>.","supplemental_guidance":"An electromagnetic pulse (EMP) is a short burst of electromagnetic energy that is spread over a range of frequencies. Such energy bursts may be natural or man-made. EMP interference may be disruptive or damaging to electronic equipment. Protective measures used to mitigate EMP risk include shielding, surge suppressors, ferro-resonant transformers, and earth grounding. EMP protection may be especially significant for systems and applications that are part of the U.S. critical infrastructure.","implementation_level":"organization","parameters":[{"id":"pe-21_odp.01","label":"protective measures"},{"id":"pe-21_odp.02","label":"system and system components"}],"methods":[{"method":"examine","label":"PE-21-Examine"},{"method":"interview","label":"PE-21-Interview"},{"method":"test","label":"PE-21-Test"}],"related_controls":["PE-18","PE-19"]},{"id":"PE-22","oscal_id":"pe-22","family":"PE","title":"Component Marking","statement":"Mark <system hardware components> indicating the impact level or classification level of the information permitted to be processed, stored, or transmitted by the hardware component.","supplemental_guidance":"Hardware components that may require marking include input and output devices. Input devices include desktop and notebook computers, keyboards, tablets, and smart phones. Output devices include printers, monitors/video displays, facsimile machines, scanners, copiers, and audio devices. Permissions controlling output to the output devices are addressed in [AC-3](#ac-3) or [AC-4](#ac-4) . Components are marked to indicate the impact level or classification level of the system to which the devices are connected, or the impact level or classification level of the information permitted to be output. Security marking refers to the use of human-readable security attributes. Security labeling refers to the use of security attributes for internal system data structures. Security marking is generally not required for hardware components that process, store, or transmit information determined by organizations to be in the public domain or to be publicly releasable. However, organizations may require markings for hardware components that process, store, or transmit public information in order to indicate that such information is publicly releasable. Marking of system hardware components reflects applicable laws, executive orders, directives, policies, regulations, and standards.","implementation_level":"organization","parameters":[{"id":"pe-22_odp","label":"system hardware components"}],"methods":[{"method":"examine","label":"PE-22-Examine"},{"method":"interview","label":"PE-22-Interview"},{"method":"test","label":"PE-22-Test"}],"references":[{"title":"IR 8023"}],"related_controls":["AC-3","AC-4","AC-16","MP-3"]},{"id":"PE-23","oscal_id":"pe-23","family":"PE","title":"Facility Location","statement":"a. Plan the location or site of the facility where the system resides considering physical and environmental hazards; and\nb. For existing facilities, consider the physical and environmental hazards in the organizational risk management strategy.","supplemental_guidance":"Physical and environmental hazards include floods, fires, tornadoes, earthquakes, hurricanes, terrorism, vandalism, an electromagnetic pulse, electrical interference, and other forms of incoming electromagnetic radiation. The location of system components within the facility is addressed in [PE-18](#pe-18).","implementation_level":"organization","objectives":[{"id":"pe-23_obj.a","label":"PE-23a.","text":"the location or site of the facility where the system resides is planned considering physical and environmental hazards;"},{"id":"pe-23_obj.b","label":"PE-23b.","text":"for existing facilities, physical and environmental hazards are considered in the organizational risk management strategy."}],"methods":[{"method":"examine","label":"PE-23-Examine"},{"method":"interview","label":"PE-23-Interview"},{"method":"test","label":"PE-23-Test"}],"related_controls":["CP-2","PE-18","PE-19","PM-8","PM-9","RA-3"]}]};
